fn copy(a: &Vec<u64>) -> Vec<u64> {
    // Pre-allocate a vector with the same capacity as `a` to avoid reallocations.
    let mut b = Vec::with_capacity(a.len());
    // Iterate over each element in `a` and push a copy into `b`.
    for &elem in a.iter() {
        b.push(elem);
    }
    b
}

